function parseIso(iso){ if(typeof iso!=='string'||!iso) return null; const t=Date.parse(iso); return Number.isFinite(t)?t:null; }
function deriveStatus(sub){ if(sub&&typeof sub==='object'){ if(sub.workflow_state==='graded'||(sub.grade!=null&&sub.grade!=='')) return 'graded'; if(sub.missing===true) return 'missing'; if(sub.workflow_state==='submitted'||sub.submitted_at) return sub.late?'late':'submitted'; if(sub.late===true) return 'late'; } return 'pending'; }
function parseOne(raw, courseName){ if(!raw||typeof raw!=='object') return null; const pl=raw.plannable||null; const title=(typeof raw.name==='string'&&raw.name.trim())||(pl&&typeof pl.title==='string'&&pl.title.trim())||''; if(!title) return null; const courseId=raw.course_id!=null?String(raw.course_id):null; const rawId=raw.id!=null?String(raw.id):(raw.plannable_id!=null?String(raw.plannable_id):(pl&&pl.id!=null?String(pl.id):title)); const id=courseId?(courseId+':'+rawId):rawId; const dueTs=parseIso(raw.due_at!=null?raw.due_at:(pl?pl.due_at:null)); const course=(typeof raw.context_name==='string'&&raw.context_name)||(courseId?(courseName.get(courseId)||''):'')||''; return { id: id, course: course, title: title, due_ts: dueTs, status: deriveStatus(raw.submission), url: typeof raw.html_url==='string'?raw.html_url:null }; }
function parseCanvasObligations(assignments, courses){ const courseName=new Map(); if(Array.isArray(courses)){ for(const c of courses){ if(c&&c.id!=null&&typeof c.name==='string') courseName.set(String(c.id), c.name); } } if(!Array.isArray(assignments)) return []; const byId=new Map(); for(const raw of assignments){ const ob=parseOne(raw, courseName); if(ob) byId.set(ob.id, ob); } return Array.from(byId.values()); }
function uuid(){ return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(ch){ const r=Math.random()*16|0; return (ch==='x'?r:(r&0x3|0x8)).toString(16); }); }
const fetchedTs = Date.now();
const c = $('Canvas Courses').first().json;
const p = $('Canvas Planner').first().json;
const coursesBody = c ? c.body : null;
const plannerBody = p ? p.body : null;
const ok = !!c && !!p && c.statusCode===200 && p.statusCode===200 && Array.isArray(coursesBody) && Array.isArray(plannerBody);
const obligations = ok ? parseCanvasObligations(plannerBody, coursesBody) : [];
const event = { id: uuid(), user_id: $env.ARCANUM_USER_ID, type: 'canvas.synced', ts: fetchedTs, device_id: $env.ARCANUM_DEVICE_ID || 'n8n-canvas', goal_id: null, module_id: null, payload: { fetched_ts: fetchedTs, ok: ok, obligations: obligations }, v: 1 };
return [{ json: event }];
